insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
select 'internet-browser', 'Segui il percorso dall''indirizzo e dalla risoluzione DNS fino a HTTP, HTML, CSS, JavaScript e ai pixel mostrati dal browser.', n.id,
  case when n.id is null then 'internet-browser' else null end,
  '{"slug":"internet-browser","title":"Internet & Browser","subtitle":"Dall''indirizzo ai pixel","phases":[{"id":"navigation","label":"Navigazione","hint":"URL e DNS","icon":"terminal"},{"id":"network","label":"Rete","hint":"Connessione e HTTP","icon":"server"},{"id":"documents","label":"Documenti","hint":"HTML, CSS e JavaScript","icon":"code"},{"id":"rendering","label":"Rendering","hint":"Dagli alberi ai pixel","icon":"code"}],"steps":[{"id":"url","phase":"navigation","illustration":"internet-browser","title":"Un indirizzo nel browser","description":"Il browser interpreta la URL: lo schema indica il protocollo, il dominio identifica l''host e il percorso la risorsa richiesta.","panels":[{"kind":"text","label":"Esempio","content":"https://esempio.it/articoli\nhttps = schema · esempio.it = host · /articoli = percorso"}]},{"id":"dns","phase":"navigation","illustration":"internet-browser","title":"Risoluzione DNS","description":"Se serve, il nome di dominio viene risolto in un indirizzo IP. Le risposte possono essere già presenti in cache; il resolver può altrimenti consultare la gerarchia DNS.","panels":[{"kind":"text","label":"Risoluzione","content":"esempio.it → resolver DNS → indirizzo IP\nLa cache può evitare una nuova ricerca."}]},{"id":"connection","phase":"network","illustration":"internet-browser","title":"Connessione sicura","description":"Per HTTPS il browser stabilisce o riutilizza una connessione sicura e verifica il certificato del server. Il trasporto dipende dalla versione HTTP: HTTP/3 usa QUIC su UDP.","panels":[{"kind":"text","label":"HTTPS","content":"HTTP/1.1 e HTTP/2: normalmente TCP + TLS\nHTTP/3: QUIC su UDP, con TLS integrato"}]},{"id":"request","phase":"network","illustration":"internet-browser","title":"Richiesta e risposta HTTP","description":"Il browser invia una richiesta; il server restituisce uno stato, degli header e, quando previsto, un corpo. Cache, redirect ed errori possono cambiare il percorso.","panels":[{"kind":"text","label":"Esempio semplificato","content":"GET /articoli HTTP/1.1\nHost: esempio.it\n\nHTTP/1.1 200 OK\nContent-Type: text/html"}]},{"id":"html","phase":"documents","illustration":"internet-browser","title":"HTML e DOM","description":"Il browser analizza l''HTML e costruisce il DOM, una rappresentazione ad albero del documento. Può iniziare mentre la risposta è ancora in arrivo.","panels":[{"kind":"code","label":"index.html","language":"html","content":"<!doctype html>\n<html lang=\"it\">\n  <head><link rel=\"stylesheet\" href=\"/stile.css\"></head>\n  <body><h1>Ciao Web</h1></body>\n</html>"},{"kind":"text","label":"DOM semplificato","content":"document → html → body → h1 → «Ciao Web»"}]},{"id":"css","phase":"documents","illustration":"internet-browser","title":"CSS e CSSOM","description":"I fogli di stile vengono scaricati e analizzati per costruire il CSSOM. Le regole determinate dalla cascata contribuiscono agli stili calcolati degli elementi.","panels":[{"kind":"code","label":"stile.css","language":"css","content":"h1 {\n  color: teal;\n  font-size: 2rem;\n}"}]},{"id":"javascript","phase":"documents","illustration":"internet-browser","title":"Il ruolo di JavaScript","description":"Gli script possono leggere e modificare DOM e stili, avviare richieste e rendere necessario un nuovo rendering. Il caricamento dipende anche da async, defer e tipo di script.","panels":[{"kind":"code","label":"Esempio","language":"js","content":"document.querySelector(\"h1\").textContent = \"Ciao browser\";"}]},{"id":"tree","phase":"rendering","illustration":"internet-browser","title":"Dai dati alla rappresentazione visiva","description":"Il browser combina DOM e stili calcolati in una rappresentazione per il rendering. Gli elementi senza box visibile, come quelli con display: none, non sono disegnati.","panels":[{"kind":"text","label":"Modello semplificato","content":"DOM + stili calcolati → render tree\nNon tutti i nodi DOM producono un box visibile."}]},{"id":"layout","phase":"rendering","illustration":"internet-browser","title":"Layout e paint","description":"Il layout calcola dimensioni e posizioni dei box; il paint determina le operazioni di disegno, come testo, colori e bordi.","panels":[{"kind":"text","label":"Dal box al disegno","content":"Layout → posizione e dimensione\nPaint → testo, sfondi, bordi e altri elementi visivi"}]},{"id":"pixels","phase":"rendering","illustration":"internet-browser","title":"Compositing e pixel","description":"Il browser combina i livelli necessari per mostrare il risultato sullo schermo. Le modifiche successive possono riattivare solo alcune fasi, non sempre l''intera pipeline.","panels":[{"kind":"text","label":"Un processo continuo","content":"Compositing → immagine sullo schermo\nInterazioni, animazioni o nuove risorse possono aggiornare la pagina."}]}]}'::jsonb
from (select 1) seed left join public.nodes n on n.slug = 'internet-browser'
on conflict (slug) do nothing;

insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
select 'http-protocol', 'Segui una chiamata dal frontend all''API e al database, poi osserva la risposta tornare al browser per aggiornare l''interfaccia.', n.id,
  case when n.id is null then 'http-protocol' else null end,
  '{"slug":"http-protocol","title":"Il ciclo di una richiesta Web","subtitle":"Dal browser ai dati e ritorno","phases":[{"id":"client","label":"Client","hint":"Interazione e interfaccia","icon":"terminal"},{"id":"request","label":"Richiesta HTTP","hint":"Metodo, header e body","icon":"code"},{"id":"server","label":"Server","hint":"API e logica applicativa","icon":"server"},{"id":"data","label":"Dati e risposta","hint":"Database e ritorno al client","icon":"database"}],"steps":[{"id":"interaction","phase":"client","illustration":"web-request-cycle","title":"Un''azione nel browser","description":"Una persona compie un''azione nell''interfaccia, per esempio confermare un ordine. Il frontend decide quale risorsa contattare e quali dati inviare.","panels":[{"kind":"text","label":"Esempio","content":"Azione: conferma ordine\nRisorsa: /api/ordini\nDati: prodotto p42, quantità 1"}]},{"id":"prepare","phase":"client","illustration":"web-request-cycle","title":"Il frontend prepara la chiamata","description":"Il codice client sceglie il metodo HTTP e prepara header e body. I dati strutturati sono serializzati, spesso in JSON, prima di essere inviati.","panels":[{"kind":"code","label":"frontend.js","language":"js","content":"const response = await fetch(\"/api/ordini\", {\n  method: \"POST\",\n  headers: { \"Content-Type\": \"application/json\" },\n  body: JSON.stringify({ productId: \"p42\", quantity: 1 }),\n});"}]},{"id":"http-request","phase":"request","illustration":"web-request-cycle","title":"La richiesta viaggia via HTTP","description":"La richiesta identifica il metodo e il percorso; gli header descrivono il contenuto e il body trasporta i dati. Con HTTPS, TLS protegge la comunicazione in transito.","panels":[{"kind":"text","label":"Richiesta semplificata","content":"POST /api/ordini\nContent-Type: application/json\n\n{ \"productId\": \"p42\", \"quantity\": 1 }"}]},{"id":"routing","phase":"server","illustration":"web-request-cycle","title":"L''API riceve e instrada","description":"Il server web riceve la richiesta e la passa all''endpoint corrispondente. Middleware e controlli, se previsti, possono verificare formato, autenticazione e autorizzazioni.","panels":[{"kind":"text","label":"Instradamento","content":"POST /api/ordini\n→ endpoint che crea un ordine\n→ parsing e controlli della richiesta"}]},{"id":"business-logic","phase":"server","illustration":"web-request-cycle","title":"Il backend applica le regole","description":"La logica applicativa controlla che l''operazione sia valida, applica le regole di business e coordina i servizi o l''accesso ai dati necessari.","panels":[{"kind":"text","label":"Responsabilità","content":"Verifica i dati\nApplica le regole dell''ordine\nDecide quali dati leggere o salvare"}]},{"id":"database-query","phase":"data","illustration":"web-request-cycle","title":"Il server legge o salva i dati","description":"Se l''operazione richiede persistenza, il backend interroga il database. Una scrittura può creare l''ordine e restituire al server il record risultante.","panels":[{"kind":"code","label":"Query parametrizzata","language":"sql","content":"INSERT INTO orders (product_id, quantity)\nVALUES ($1, $2)\nRETURNING id, status;"}]},{"id":"database-result","phase":"data","illustration":"web-request-cycle","title":"Il risultato torna al backend","description":"Il database restituisce il risultato dell''operazione. Il backend lo usa per costruire una risposta adatta al contratto dell''API.","panels":[{"kind":"table","label":"Record creato","columns":["id","status"],"rows":[["ord_1042","confirmed"]],"highlightRows":[0]}]},{"id":"http-response","phase":"data","illustration":"web-request-cycle","title":"Il server invia la risposta HTTP","description":"La risposta contiene un codice di stato, header e, quando previsto, un body. Per esempio, 201 indica che una risorsa è stata creata; errori e redirect seguono percorsi diversi.","panels":[{"kind":"text","label":"Risposta semplificata","content":"HTTP/1.1 201 Created\nContent-Type: application/json\n\n{ \"id\": \"ord_1042\", \"status\": \"confirmed\" }"}]},{"id":"render-ui","phase":"client","illustration":"web-request-cycle","title":"Il frontend aggiorna la pagina","description":"Il client legge la risposta e aggiorna l''interfaccia. `fetch` non considera automaticamente un 4xx o 5xx un errore di rete: il codice deve controllare `response.ok`; un problema di rete, invece, può interrompere la chiamata.","panels":[{"kind":"code","label":"Gestione della risposta","language":"js","content":"if (!response.ok) {\n  throw new Error(`Richiesta fallita: ${response.status}`);\n}\n\nconst order = await response.json();\nshowOrderConfirmation(order);"}]}]}'::jsonb
from (select 1) seed left join public.nodes n on n.slug = 'http-protocol'
on conflict (slug) do nothing;

insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
select 'prisma-orm', 'Segui una richiesta Express attraverso Prisma Client e SQL parametrizzato fino alla riga creata nel database e alla risposta al client.', n.id,
  case when n.id is null then 'prisma-orm' else null end,
  '{"slug":"prisma-orm","title":"Prisma ORM","subtitle":"Dal codice Express alla riga nel database","phases":[{"id":"express","label":"Express","hint":"Richiesta HTTP","icon":"server"},{"id":"prisma","label":"Prisma Client","hint":"Query type-safe","icon":"code"},{"id":"sql","label":"SQL","hint":"Traduzione","icon":"terminal"},{"id":"database","label":"Database","hint":"Postgres / Supabase","icon":"database"}],"steps":[{"id":"request","phase":"express","illustration":"prisma-flow","title":"Richiesta in arrivo","description":"Il client invia POST /users con un JSON. Express esegue il parsing del body e passa il controllo all''handler della rotta.","panels":[{"kind":"code","label":"server.js","language":"js","content":"import express from \"express\";\nimport { prisma } from \"./lib/prisma.js\";\n\nconst app = express();\napp.use(express.json());\n\napp.post(\"/users\", async (req, res) => {\n  const { email, name } = req.body;\n\n  const user = await prisma.user.create({\n    data: { email, name },\n  });\n\n  res.status(201).json(user);\n});","highlightLines":[7,8,9]},{"kind":"text","label":"Richiesta HTTP","content":"POST /users\nContent-Type: application/json\n\n{ \"email\": \"ada@example.com\", \"name\": \"Ada Lovelace\" }"}]},{"id":"client-call","phase":"prisma","illustration":"prisma-flow","title":"Chiamata a Prisma Client","description":"L''handler chiama prisma.user.create(). Il client è generato dallo schema, quindi `data` è tipizzato e validato prima di toccare il database.","panels":[{"kind":"code","label":"Prisma Client","language":"js","content":"const user = await prisma.user.create({\n  data: {\n    email: \"ada@example.com\",\n    name: \"Ada Lovelace\",\n  },\n});","highlightLines":[1,2,3,4,5,6]}]},{"id":"translation","phase":"sql","illustration":"prisma-flow","title":"Traduzione in SQL","description":"Il query engine converte la chiamata in una query SQL parametrizzata: i valori viaggiano come parametri, non concatenati (niente SQL injection).","panels":[{"kind":"code","label":"Prisma Client","language":"js","content":"const user = await prisma.user.create({\n  data: {\n    email: \"ada@example.com\",\n    name: \"Ada Lovelace\",\n  },\n});"},{"kind":"code","label":"Query generata","language":"sql","content":"INSERT INTO \"public\".\"User\" (\"id\", \"email\", \"name\", \"createdAt\")\nVALUES ($1, $2, $3, $4)\nRETURNING \"id\", \"email\", \"name\", \"createdAt\";\n\n-- $1 = ''a1f3…''  $2 = ''ada@example.com''\n-- $3 = ''Ada Lovelace''  $4 = NOW()"}]},{"id":"write","phase":"database","illustration":"prisma-flow","title":"Scrittura sul database","description":"Postgres esegue l''INSERT. La riga compare nella tabella User e RETURNING restituisce il record creato.","panels":[{"kind":"table","label":"Tabella \"User\"","columns":["id","email","name","createdAt"],"rows":[["c0b2…","grace@example.com","Grace Hopper","2026-11-04 09:12"],["a1f3…","ada@example.com","Ada Lovelace","2026-11-05 17:48"]],"highlightRows":[1]}]},{"id":"response","phase":"express","illustration":"prisma-flow","title":"Risposta al client","description":"Prisma restituisce l''oggetto creato; Express risponde con 201 e il JSON del nuovo utente.","panels":[{"kind":"text","label":"Risposta HTTP","content":"HTTP/1.1 201 Created\nContent-Type: application/json\n\n{ \"id\": \"a1f3…\", \"email\": \"ada@example.com\", \"name\": \"Ada Lovelace\" }"}]}]}'::jsonb
from (select 1) seed left join public.nodes n on n.slug = 'prisma-orm'
